sys_script_client.script:
function onLoad() {
    // -----------------------------------------------------------------
    // QA finding F14 - "Blocked-save banners accumulate instead of
    // flushing". When a save is refused because a mandatory field is
    // empty, the platform APPENDS its banner into #output_messages
    // without flushing the banner left by the previous attempt. Filling
    // one of the named fields and retrying therefore leaves the screen
    // asserting two contradictory things at once - the stale banner
    // still names Subject as empty while Subject visibly contains text -
    // and every retry adds another 40.5px of banner.
    //
    // The fix is to flush the message region at the ONLY moment the
    // contradiction can be created: when the user edits one of the
    // mandatory fields the stale banner is talking about. Clearing then
    // is safe by construction - the flush happens strictly BEFORE the
    // next save attempt, so it can never erase a freshly written
    // message, and a message that was never contradicted is never
    // touched: a server-written banner survives a fresh reload
    // untouched, which is what AAP Section 0.7.4 requires of the three
    // verbatim state-machine messages ("All tasks must be closed before
    // resolving this case.", "Cases cannot be returned to Draft.",
    // "Closed cases are terminal and cannot be modified.").
    //
    // WHY THIS IS AN onLoad SCRIPT AND NOT onSubmit OR onChange
    //   An onSubmit flush is only correct if the platform writes its
    //   mandatory-field banner AFTER onSubmit client scripts run, and
    //   that ordering was deliberately not relied on: the platform is
    //   documented to abort the submit when a mandatory field is empty
    //   without reaching onSubmit client scripts, which would leave the
    //   flush unrun on precisely the saves that produce these banners.
    //   A single onChange script would fix only ONE field -
    //   sys_script_client.field holds one field name - and this table
    //   has four mandatory fields (subject, status, description,
    //   requester_name, all mandatory=true in sys_dictionary), so a
    //   per-field script would leave three of the four contradictions
    //   in place. Binding all four from one onLoad script keeps the
    //   application to a single client-script record (AAP Section 0.7.2
    //   minimal change) while covering every field the banner can name.
    // -----------------------------------------------------------------
    'use strict';

    // The mandatory fields of x_casemgmt_case - the only fields the
    // platform's mandatory-field banner can ever name on this form.
    // Kept as an explicit list rather than derived at runtime because
    // g_form exposes no "list the mandatory fields" API, and because an
    // explicit list makes the intended coverage reviewable.
    var MANDATORY_FIELDS = ['subject', 'status', 'description', 'requester_name'];

    // UI16 renders form-level messages into this container; each banner
    // is a child carrying the class "outputmsg".
    var MESSAGE_CONTAINER_ID = 'output_messages';
    var MESSAGE_CLASS = 'outputmsg';

    // Marker property so a control is never bound twice, e.g. if the
    // platform re-runs onLoad against a DOM that is already wired.
    var BOUND_FLAG = 'xCasemgmtFlushStaleMessagesBound';

    /**
     * True when at least one form-level message is currently on screen.
     * Used only to avoid pointless work while the user types; when the
     * container cannot be inspected the answer is TRUE, so the flush
     * still happens and message hygiene never depends on the probe.
     */
    function messagesPresent() {
        try {
            var box = document.getElementById(MESSAGE_CONTAINER_ID);
            if (!box) {
                return true;
            }
            return box.getElementsByClassName(MESSAGE_CLASS).length > 0;
        } catch (probeError) {
            return true;
        }
    }

    /**
     * Flush the stale banner. Wrapped so that no failure in message
     * hygiene can ever interfere with data entry on the form.
     */
    function flushStaleMessages() {
        try {
            if (messagesPresent()) {
                g_form.clearMessages();
            }
        } catch (flushError) {
            // Monitoring hook: surfaces in the browser console via the
            // platform's own client-side logger, without breaking the
            // form.
            if (typeof jslog === 'function') {
                jslog('x_casemgmt_case_flush_stale_messages: could not clear form messages: ' + flushError);
            }
        }
    }

    var bound = 0;
    var skipped = [];

    for (var i = 0; i < MANDATORY_FIELDS.length; i++) {
        var fieldName = MANDATORY_FIELDS[i];
        var control = null;

        try {
            control = g_form.getControl(fieldName);
        } catch (controlError) {
            control = null;
        }

        // A control is absent when the field is not on this view or the
        // field-level ACLs in the application's acl/ folder deny the
        // current user access to it. Both are legitimate states, so the
        // field is skipped rather than treated as an error.
        if (!control || !control.addEventListener) {
            skipped.push(fieldName);
            continue;
        }

        if (control[BOUND_FLAG]) {
            continue;
        }
        control[BOUND_FLAG] = true;

        // "input" catches the first keystroke, a paste, a drag-and-drop
        // and a browser autofill; "change" catches a choice selection
        // and a commit-on-blur. Both are registered because neither
        // covers every control type on its own, and the messagesPresent()
        // guard makes the second call of a pair a no-op.
        control.addEventListener('input', flushStaleMessages, false);
        control.addEventListener('change', flushStaleMessages, false);
        bound++;
    }

    if (typeof jslog === 'function') {
        jslog('x_casemgmt_case_flush_stale_messages: bound ' + bound + ' of ' +
            MANDATORY_FIELDS.length + ' mandatory field control(s)' +
            (skipped.length ? '; not on form or not readable: ' + skipped.join(', ') : ''));
    }
}
